  "sqlQuery": "SELECT product_id, product_name, SUM(quantity_sold) AS total_sold FROM sales WHERE sale_date >= date_trunc('month', CURRENT_DATE) AND sale_date < date_trunc('month', CURRENT_DATE) + INTERVAL '1 month' GROUP BY product_id, product_name ORDER BY total_sold DESC LIMIT 10;",
  "explanation": "This query retrieves the top 10 products with the highest total quantity sold in the current month. It assumes a 'sales' table with 'product_id', 'product_name', 'quantity_sold', and 'sale_date' columns."
}

